; Ultima IV: Quest of the Avatar (Sega Master System)
; Disassembly that rebuilds the original ROM byte-for-byte with WLA-DX.
; Generated by tools/disasm.py; see README.md.

.MEMORYMAP
SLOTSIZE $4000
DEFAULTSLOT 0
SLOT 0 $0000
SLOT 1 $4000
SLOT 2 $8000
.ENDME

.ROMBANKMAP
BANKSTOTAL 32
BANKSIZE $4000
BANKS 32
.ENDRO

.EMPTYFILL $FF

; work RAM variables (tools/hints.txt)
.DEFINE port_dd_prev             $C006	; last read of port $DD (reset button edge)
.DEFINE vblank_count             $C00A	; incremented every interrupt
.DEFINE frames_this_loop         $C00B	; copy of vblank_count taken by main_loop
.DEFINE irq_callback             $C00D	; routine the interrupt handler jumps to
.DEFINE pad_mode                 $C0AE	; nonzero: combine both pads
.DEFINE joy_held                 $C0AF	; buttons down now (1 = pressed, bits UDLR12)
.DEFINE joy_pressed              $C0B0	; buttons that went down this frame
.DEFINE joy_dir                  $C0B1	; direction code from the D-pad (table $06BD)
.DEFINE input_noise              $C0B5	; sum of joypad readings, mixed into random
.DEFINE rng_seed                 $C0B6
.DEFINE music_playing            $C0B8	; current tune for play_music
.DEFINE wait_flag_value          $C0C7
.DEFINE main_loop_count          $C0C8	; 16-bit, +1 per main loop pass
.DEFINE message_bank             $C0CA
.DEFINE message_table            $C0CB
.DEFINE task_slots               $C300	; 10 x 48 bytes
.DEFINE talk_flags               $C580	; +topic: 1 once asked; $C595/$C596 keyword 1/2 shown
.DEFINE game_mode                $C600	; index into game_mode_table
.DEFINE text_col                 $C639
.DEFINE text_row                 $C63A
.DEFINE location_people          $C651	; 256-byte people/object block of the current location
.DEFINE party                    $C751	; +0 hp, +2 max hp, +4 xp (16-bit each), +6 str, +7 dex, +8 int, +9 mp, +A level, +B weapon, +C armour, +D name
.DEFINE party_name               $C75E	; the Avatar's name (party + $0D)
.DEFINE room_monsters            $C839	; 16 x 8 bytes: +0/+1 x,y, +4 hp, +5 graphic
.DEFINE party_objects            $C8B9	; 5 bytes per member: screen figure (+2/+3 graphic)
.DEFINE move_count               $C901	; +1 per step (32-bit?)
.DEFINE food_fraction            $C906	; counts down per step
.DEFINE food                     $C907	; 16-bit, shown as F:
.DEFINE gold                     $C909	; 16-bit, shown as G:
.DEFINE karma                    $C90B	; 8 bytes, one per virtue (Honesty..Humility)
.DEFINE weapons_owned            $C91F	; count per weapon
.DEFINE reagents                 $C92F	; 8 counts
.DEFINE mixtures                 $C937	; 26 counts, max 99
.DEFINE party_x                  $C953	; world/town X (PC Ultima IV coordinates)
.DEFINE party_y                  $C954
.DEFINE party_size               $C957
.DEFINE last_karma_time          $C96B	; moves/16 when karma for giving/answering was last granted ($33F6)
.DEFINE world_return_x           $C96D	; where leaving a town puts the party
.DEFINE world_return_y           $C96E
.DEFINE world_x_saved            $C971
.DEFINE world_y_saved            $C972
.DEFINE shop_number              $C983	; 0-based, of the current shop
.DEFINE view_x                   $C985	; party position inside the loaded map window
.DEFINE view_y                   $C986
.DEFINE view_chunk_x             $C987	; which 16-tile chunk the window starts at
.DEFINE view_chunk_y             $C988
.DEFINE map_mode                 $C99F	; 0/1 world, towns; 2 dungeon; 3-5 combat
.DEFINE location                 $C9A0	; 0 = world, 1-17 = settlement (table bank15:$8077)
.DEFINE talk_question_topic      $C9A9
.DEFINE talk_turn_away           $C9AB
.DEFINE dungeon_room             $C9B8
.DEFINE entry_direction          $C9B9
.DEFINE slot2_bank               $DFFF	; shadow of the $FFFF mapper register

